<?php

declare(strict_types=1);

namespace Database\Seeders;

use App\Models\Zone;
use App\Support\ChurchZones;
use Illuminate\Database\Seeder;

/**
 * Seeds the church zones from the canonical {@see ChurchZones} list. Idempotent:
 * matches on name, so re-running never duplicates a zone. Existing zones keep
 * their code, pastor contact and active flag; only new names are inserted (and
 * get a referral code generated by the Zone model on create).
 */
final class ZoneSeeder extends Seeder
{
    public function run(): void
    {
        foreach (ChurchZones::all() as $name) {
            // updateOrCreate on name; the empty attribute array means existing
            // rows are untouched, and new rows trigger Zone::creating() which
            // assigns a unique code + slug.
            Zone::query()->firstOrCreate(['name' => $name]);
        }
    }
}
